parameters.jsCode:
const items = $input.all();
const extractedData = [];

items.forEach(item => {
  const responseData = item.json.data || item.json;
  const cards = responseData.cards || [];

  cards.forEach(cardWrapper => {
    const widget = cardWrapper.card?.card;
    if (!widget) return;

    const widgetType = widget['@type'];
    let itemsList = [];

    if (widgetType === 'type.googleapis.com/swiggy.gandalf.widgets.v2.GridWidget') {
      itemsList = widget.gridElements?.infoWithStyle?.items || [];
    } else if (widgetType === 'type.googleapis.com/swiggy.im.v1.OOSItemCollectionCard') {
      itemsList = widget.items?.items || [];
    }

    itemsList.forEach(prodItem => {
      const brandName = (prodItem.brand || "").toLowerCase();
      const parentProductName = prodItem.displayName || ""; 

      if (brandName.includes("cloud9") || parentProductName.toLowerCase().includes("cloud 9")) {
        const variations = prodItem.variations || [];

        variations.forEach(variant => {
          extractedData.push({
            pincode: $('Loop Over Items').first().json.pincode || "N/A",
            parent_product_name: parentProductName,
            variant_product_name: variant.displayName,
            sku_id: variant.skuId,
            size: variant.quantityDescription,
            mrp: variant.price?.mrp?.units || "N/A",
            offer_price: variant.price?.offerPrice?.units || "N/A",
            in_stock: variant.inventory?.inStock ? "Yes" : "Out of Stock",
            max_allowed_cart_qty: variant.cartAllowedQuantity?.allowedQuantity || 0
          });
        });
      }
    });
  });
});

// Ye line saare items ko flat karke return karegi taaki Excel me rows vertically aayein
return extractedData.map(item => ({ json: item }));

return [
  { json: { pincode: "400089" } },
  // { json: { pincode: "400072" } },
  // { json: { pincode: "400099" } }
  // just keep adding your pincodes here
];
